export type ParsedInitDuiInstruction<
  TProgram extends string = typeof HXUI_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    admin: TAccountMetas[0];
    liteAuthority: TAccountMetas[1];
    hxuiVault: TAccountMetas[2];
    hxuiMint: TAccountMetas[3];
    hxuiConfig: TAccountMetas[4];
    hxuiLiteMint: TAccountMetas[5];
    hxuiFreeMintCounter: TAccountMetas[6];
    hxuiDropTime: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
    tokenProgram: TAccountMetas[9];
  };
  data: InitDuiInstructionData;
};

export function parseInitDuiInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedInitDuiInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      admin: getNextAccount(),
      liteAuthority: getNextAccount(),
      hxuiVault: getNextAccount(),
      hxuiMint: getNextAccount(),
      hxuiConfig: getNextAccount(),
      hxuiLiteMint: getNextAccount(),
      hxuiFreeMintCounter: getNextAccount(),
      hxuiDropTime: getNextAccount(),
      systemProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getInitDuiInstructionDataDecoder().decode(instruction.data),
  };
}
